test('invoiceTotals returns subtotal, discount, vat, and total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 5 * 8500 + 3 * 9500);
  assert.equal(totals.subtotal, 71000);
  assert.equal(totals.discount, 0);
  const expectedVat = Math.round(71000 * 0.21);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, 71000 + expectedVat);
});

